def bmi_category(weight, height):
    bmi = weight / height ** 2
    if bmi < 18.5:
        return "نحافة"
    elif bmi < 25:
        return "طبيعي"
    elif bmi < 30:
        return "زيادة وزن"
    return "سمنة"

