def hamming(s1, s2):
    if len(s1) != len(s2):
        raise ValueError("يجب أن يتساوى الطولان")
    return sum(1 for a, b in zip(s1, s2) if a != b)

print(hamming("GAGCCTACTAACGGGAT", "CATCGTAATGACGGCCT"))  # 7

def read_fasta(path):
    seqs = {}
    name = None
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith(">"):
                name = line[1:].split()[0]
                seqs[name] = ""
            else:
                seqs[name] += line.upper()
    return seqs

for name, seq in read_fasta("genes.fasta").items():
    print(name, len(seq))

