def convert_weight(value, unit="lb"):
    if unit == "lb":
        return round(value * 0.4536, 1)
    elif unit == "kg":
        return value
    raise ValueError("وحدة غير معروفة")

print(convert_weight(150))       # 68.0
print(convert_weight(70, "kg"))  # 70

class Patient:
