class DNASequence:
    PAIRS = {"A": "T", "T": "A", "G": "C", "C": "G"}

    def __init__(self, seq):
        seq = seq.upper()
        if not set(seq) <= set("ATGC"):
            raise ValueError("تسلسل يحتوي قواعد غير صالحة")
        self.seq = seq

    def __len__(self):
        return len(self.seq)

    def gc_content(self):
        return (self.seq.count("G") + self.seq.count("C")) / len(self) * 100

    def reverse_complement(self):
        return DNASequence("".join(self.PAIRS[b] for b in reversed(self.seq)))

    def __str__(self):
        return self.seq

d = DNASequence("atgcgc")
print(len(d), round(d.gc_content(), 1), d.reverse_complement())  # 6 66.7 GCGCAT

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def describe(self):
        return f"{self.name} ({self.age})"

class Doctor(Person):
    def __init__(self, name, age, specialty):
        super().__init__(name, age)
        self.specialty = specialty

    def describe(self):
        return f"د. {super().describe()} - {self.specialty}"

