class EHR:
    def __init__(self):
        self.records = {}

    def add(self, pid, name, age):
        if pid in self.records:
            raise KeyError(f"{pid} موجود مسبقاً")
        self.records[pid] = {"name": name, "age": age}

    def find(self, pid):
        return self.records.get(pid)

    def average_age(self):
        if not self.records:
            return 0
        return sum(r["age"] for r in self.records.values()) / len(self.records)

ehr = EHR()
ehr.add("P1", "Ali", 52)
ehr.add("P2", "Sara", 31)
print(ehr.find("P2"))     # {'name': 'Sara', 'age': 31}
print(ehr.average_age())  # 41.5

class InvalidSequenceError(Exception):
    """خطأ يُرفع عند وجود قاعدة غير صالحة."""

def validate(seq):
    for pos, base in enumerate(seq.upper(), start=1):
        if base not in "ATGC":
            raise InvalidSequenceError(f"قاعدة غير صالحة '{base}' في الموقع {pos}")
    return True

try:
    validate("ATGXC")
except InvalidSequenceError as e:
    print("خطأ:", e)

def windows(seq, size, step):
    for i in range(0, len(seq) - size + 1, step):
        yield i + 1, seq[i:i + size]

seq = "ATGCGCGCATATATGCGC"
for start, win in windows(seq, 6, 3):
    gc = (win.count("G") + win.count("C")) / len(win) * 100
    print(f"{start:>3}  {win}  GC = {gc:.0f}%")

import time

def timer(func):
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"{func.__name__} استغرقت {elapsed:.4f} ثانية")
        return result
    return wrapper

@timer
def count_gc(seq):
    return sum(1 for b in seq if b in "GC")

print(count_gc("ATGC" * 100000))  # 200000

def rabbits(n, k):
    """عدد أزواج الأرانب بعد n شهراً."""
    if n <= 2:
        return 1
    return rabbits(n - 1, k) + k * rabbits(n - 2, k)

print(rabbits(5, 3))  # 19

STOPS = {"TAA", "TAG", "TGA"}

def longest_orf(seq):
    best = ""
    for frame in range(3):
        i = frame
        while i <= len(seq) - 3:
            if seq[i:i + 3] == "ATG":
                for j in range(i, len(seq) - 2, 3):
                    if seq[j:j + 3] in STOPS:
                        orf = seq[i:j + 3]
                        if len(orf) > len(best):
                            best = orf
                        break
            i += 3
    return best

print(longest_orf("CCATGAAATTTGGGTAACCATGCCCTAG"))  # ATGAAATTTGGGTAA
